package vn.edu.hcmute.khanggearver2.service.impl;
import org.springframework.context.annotation.Profile; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.edu.hcmute.khanggearver2.domain.Order; import vn.edu.hcmute.khanggearver2.domain.OrderStatus; import vn.edu.hcmute.khanggearver2.exception.BusinessRuleException; import vn.edu.hcmute.khanggearver2.exception.ResourceNotFoundException; import vn.edu.hcmute.khanggearver2.repository.OrderRepository; import vn.edu.hcmute.khanggearver2.service.OrderService;
@Service @Profile("!foundation") public class OrderServiceImpl implements OrderService { private final OrderRepository orders; public OrderServiceImpl(OrderRepository o){orders=o;} @Transactional(readOnly=true) public Page<Order> search(String k,OrderStatus s,Pageable p){return orders.search(k==null?"":k.trim(),s,p);} @Transactional(readOnly=true) public Order getById(Long id){return orders.findDetailById(id).orElseThrow(()->new ResourceNotFoundException("Khong tim thay don hang"));} @Transactional public Order updateStatus(Long id,OrderStatus next){Order o=getById(id);if(!allowed(o.getOrderStatus(),next))throw new BusinessRuleException("Khong the chuyen trang thai don hang");o.setOrderStatus(next);if(next==OrderStatus.COMPLETED)o.setPaymentStatus(vn.edu.hcmute.khanggearver2.domain.PaymentStatus.PAID);return orders.save(o);} private boolean allowed(OrderStatus from,OrderStatus to){if(from==to)return true;if(from==OrderStatus.CANCELLED||from==OrderStatus.COMPLETED)return false;if(to==OrderStatus.CANCELLED)return from==OrderStatus.PENDING||from==OrderStatus.CONFIRMED;if(from==OrderStatus.PENDING)return to==OrderStatus.CONFIRMED;if(from==OrderStatus.CONFIRMED)return to==OrderStatus.SHIPPING;return from==OrderStatus.SHIPPING&&to==OrderStatus.COMPLETED;} }
